import{_ as a,H as t,f as r,i as p}from"./chunks/framework.BH2BK_3i.js";const l=JSON.parse('{"title":"第二季回归 | 这次我们来专门聊聊V8","description":"","frontmatter":{},"headers":[],"relativePath":"浏览器工作原理与实践/第二季回归-这次我们来专门聊聊V8.md","filePath":"浏览器工作原理与实践/第二季回归-这次我们来专门聊聊V8.md","lastUpdated":1779820957000}'),i={name:"浏览器工作原理与实践/第二季回归-这次我们来专门聊聊V8.md"};function n(m,e,o,s,c,E){return t(),r("div",null,[...e[0]||(e[0]=[p('<h1 id="第二季回归-这次我们来专门聊聊v8" tabindex="-1">第二季回归 | 这次我们来专门聊聊V8 <a class="header-anchor" href="#第二季回归-这次我们来专门聊聊v8" aria-label="Permalink to &quot;第二季回归 | 这次我们来专门聊聊V8&quot;">​</a></h1><p>你好，我是李兵。在这个专栏中，我们对浏览器的工作原理进行了详细的介绍。</p><p>初期的浏览器，展示的只是一些静态页面，随着需要和页面交互的需求越来越多，JavaScript就出现在了浏览器中，它让静态的页面动了起来。目前JavaScript已成为页面中最核心的一部分了，不过，JavaScript作为一门高级语言，它的代码给到浏览器或者Node.js时，是不能直接被底层的CPU所执行的，这就需要通过JavaScript虚拟机来实现代码的编译和执行。</p><p>市面上有很多种JavaScript虚拟机，比如SpiderMonkey、V8、JavaScriptCore等，其中由谷歌开发的开源项目V8使用最为广泛。</p><p>V8主要应用于Google开源浏览器Chrome中，它拥有非常庞大的生态圈，一方面得益于全球25亿台安卓设备上的Chrome浏览器，另一方面，也和它的许多革命性设计分不开。</p><p>比如，V8摒弃了导致JavaScript执行速度过慢的解释执行方式，率先采用了即时编译（JIT）的双轮驱动的设计，混合了编译执行和解释执行两种方式。JIT作为一种权衡策略，大幅优化了JavaScript代码的执行效率，也将JavaScript虚拟机技术推向了一个全新的高度。</p><p>作为JavaScript程序员，你可能并不会去实现一个JavaScript虚拟机，不过我们还是有必要理解JavaScript虚拟机工作机制的，你可以从中学习到很多优化性能的方法，帮你写出更高效的JavaScript代码。</p><p>所以，我回到极客时间做了第二季专栏《 <a href="https://time.geekbang.org/column/intro/296?utm_term=zeusOVYAE&amp;utm_source=app&amp;utm_medium=geektime&amp;utm_campaign=296-presell&amp;utm_content=liulanqizhuanlan0316" target="_blank" rel="noreferrer">图解Google V8</a>》。在这一季里，我会专门讲讲V8的工作原理，帮你完整梳理V8的核心知识体系。在讲述方式上，我仍然延续这一季的风格，通过大量图片演示，深入浅出地讲解V8执行JavaScript代码的底层机制和原理。</p><p>希望通过这门课程，带你了解完整的V8编译流水线，同时通过对V8工作机制的学习，搞懂JavaScript语言的核心特性，进而从根源解决程序问题，加快JavaScript的执行速度。</p><p>下面是专栏的目录：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B5%8F%E8%A7%88%E5%99%A8%E5%B7%A5%E4%BD%9C%E5%8E%9F%E7%90%86%E4%B8%8E%E5%AE%9E%E8%B7%B5/images/211563/2cb0c3abcb6d7683df56353ac33beca1.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B5%8F%E8%A7%88%E5%99%A8%E5%B7%A5%E4%BD%9C%E5%8E%9F%E7%90%86%E4%B8%8E%E5%AE%9E%E8%B7%B5/images/211563/2cb0c3abcb6d7683df56353ac33beca1.jpg" alt=""></a></p><p>为了感谢老同学，我还准备了一个「专属福利」：</p><p>3 月 16 日，专栏上新时，我会送你一张 10 元专属优惠券，可与限时优惠同享，有效期 48 小时，建议尽早使用。</p><p><strong>点击下方图片</strong>，立即免费试读新专栏。</p><p><a href="https://time.geekbang.org/column/intro/296?utm_term=zeusOVYAE&amp;utm_source=app&amp;utm_medium=geektime&amp;utm_campaign=296-presell&amp;utm_content=liulanqizhuanlan0316" target="_blank" rel="noreferrer"><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B5%8F%E8%A7%88%E5%99%A8%E5%B7%A5%E4%BD%9C%E5%8E%9F%E7%90%86%E4%B8%8E%E5%AE%9E%E8%B7%B5/images/211563/c485757bed7d2269fe02048011a5f5c4.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%B5%8F%E8%A7%88%E5%99%A8%E5%B7%A5%E4%BD%9C%E5%8E%9F%E7%90%86%E4%B8%8E%E5%AE%9E%E8%B7%B5/images/211563/c485757bed7d2269fe02048011a5f5c4.jpg" alt=""></a></a></p><p>一段新的征程，期待与你见证成长！我在《 <a href="https://time.geekbang.org/column/intro/296?utm_term=zeusOVYAE&amp;utm_source=app&amp;utm_medium=geektime&amp;utm_campaign=296-presell&amp;utm_content=liulanqizhuanlan0316" target="_blank" rel="noreferrer">图解Google V8</a>》等你。</p>',16)])])}const u=a(i,[["render",n]]);export{l as __pageData,u as default};
